WITH lines AS (SELECT id, created_at, coupon_codes, line.qty, line.price, line.promo FROM carts LATERAL VIEW EXPLODE(items) t AS line), with_windows AS (SELECT id, created_at, coupon_codes, qty, price, promo, ROUND(price / SUM(price) OVER (PARTITION BY promo), 4) AS price_share, COUNT(price) OVER w_running AS promo_count_price FROM lines WINDOW w_running AS (PARTITION BY promo)), with_windows_carts AS (SELECT *, DENSE_RANK() OVER (PARTITION BY promo ORDER BY qty DESC NULLS LAST) AS qty_dense_rank, ROUND(price / SUM(price) OVER (PARTITION BY promo), 4) AS price_share_2 FROM with_windows), base AS (SELECT *, ARRAY_CONTAINS(coupon_codes, 'SPRING10') AS is_spring10 FROM with_windows_carts WHERE created_at >= DATE '2025-03-02' AND promo IS NOT NULL AND qty_dense_rank IS NULL) SELECT id, created_at, coupon_codes, qty, price, promo, price_share, promo_count_price, qty_dense_rank, price_share_2, is_spring10, RANK() OVER (PARTITION BY promo ORDER BY price_share_2 DESC NULLS FIRST) AS price_share_2_rank, COUNT(price_share) OVER (PARTITION BY promo) AS promo_count_price_share FROM base
